def length(locations: List['Location']=[], _3d: bool=False) ->float:
    if not locations:
        return 0

    total = 0
    for i in range(len(locations) - 1):
        if _3d:
            total += locations[i].distance_3d(locations[i+1])
        else:
            total += locations[i].distance_2d(locations[i+1])

    return total


def length_3d(locations: List['Location']=[]) ->float:
    return length(locations, True)
